insert into faqs (question, answer, page_slug, display_order) values
('Do Uber/Ola work in Ooty?', 'No — the hill station''s taxi industry runs on local unions with fixed rates. We arrange a driver in advance so you''re not negotiating on arrival.', 'faq', 1),
('Do I need an E-Pass to enter Ooty?', 'Yes, mandatory for all non-Tamil Nadu registered vehicles — apply free online, takes about 5 minutes. Ask us if you need help.', 'faq', 2),
('How cold does Ooty actually get?', 'Even in summer, evenings need a light jacket; December-February can drop to 5-15°C. Pack layers regardless of season.', 'faq', 3),
('Do you have confirmed hotel/taxi partners yet?', 'We''re onboarding verified local partners; meanwhile our team personally arranges your stay and travel to your requirements.', 'faq', 4),
('What''s the actual best time to visit Ooty? I''ve seen conflicting advice.', 'October to June generally has the clearest weather for sightseeing. Monsoon (June-September) has real appeal too — lush greenery, fewer crowds — but comes with landslide/road-closure risk. Tell us what you value more and we''ll tell you which window fits.', 'faq', 5),
('Is Ooty overcrowded and overrated?', 'Some of the most-photographed spots can feel that way, especially on weekends at the wrong hour. The Nilgiris itself isn''t overrated — the standard circuit, seen at the wrong time, sometimes is.', 'faq', 6),
('Could my trip be disrupted by a VIP visit or road closure?', 'Uncommon but possible — official visits have caused over an hour of unexpected closure before. We''ll adjust your day''s plan in real time if it happens.', 'faq', 7),
('How do you make sure a stay is actually good?', 'Someone from our team sees a property directly before it goes on our list — not just photos from the owner.', 'faq', 8),
('What''s the difference between OotyMade.com and OotyMade Tourism?', 'OotyMade.com ships Nilgiris products across India. OotyMade Tourism, same Ooty team, arranges the trip itself.', 'faq', 9);
